const moduleMap = new Map(modules.map((m) => [m.id, m]));
const moduleNameMap = new Map(modules.map((m) => [m.short, m]));

// Pre-computed category index: maps category name → sorted module list
const categoryModulesMap = new Map<string, ModuleDefinition[]>();
for (const m of modules) {
	const name = m.page?.name;
	if (name) {
		if (!categoryModulesMap.has(name)) categoryModulesMap.set(name, []);
		categoryModulesMap.get(name)!.push(m);
	}
}
for (const mods of categoryModulesMap.values()) mods.sort((a, b) => (a.page?.ord ?? 999) - (b.page?.ord ?? 999));
const sortedCategories = Array.from(categoryModulesMap.entries())
	.sort(([, a], [, b]) => (a[0]?.page?.ord ?? 999) - (b[0]?.page?.ord ?? 999))
	.map(([name]) => name);

export function getModule(id: number): ModuleDefinition | undefined {
	return moduleMap.get(id);
}

const FX_IN_TYPE_ID = 127;

// The official editor's per-module context mask (CBuildModule::IsValidContext, read from the Mac v1.62 binary)
// allows every module in both areas except Fx-In, which only works in the FX area.
export function isValidInArea(typeId: number, area: 'voice' | 'fx'): boolean {
	return area === 'fx' || typeId !== FX_IN_TYPE_ID;
}

const VOCODER_TYPE_ID = 108;

// Vocoder preset "0": analysis band i feeds synthesis band i+1 (0 = Off), which is what makes the graph show.
export function vocoderPreset0(bandIndex: number): number {
	return bandIndex + 1;
}

export function getParamDefault(p: ModuleParam): number {
	return p.def ?? getParam(p.type)?.def ?? 64;
}

export function getDefaultParamValues(typeId: number): number[] {
	const values = (getModule(typeId)?.params ?? []).map(getParamDefault);
	if (typeId === VOCODER_TYPE_ID) for (let i = 0; i < 16; i++) values[i] = vocoderPreset0(i);
	return values;
}

// Param indices in the original editor's navigation order (left/right arrows).
export function getParamNavOrder(def: ModuleDefinition): number[] {
	return def.paramOrder ?? (def.params ?? []).map((_, i) => i);
}

// Param indices Assign puts on knobs: navigation order minus the params the original skips.
export function getAssignableParams(def: ModuleDefinition): number[] {
	return getParamNavOrder(def).filter((i) => !def.assignSkip?.includes(i));
}

export function getAllModules(): ModuleDefinition[] {
	return modules;
}

export function getAllCategories(): string[] {
	return sortedCategories;
}

export function getModulesByCategory(categoryName: string): ModuleDefinition[] {
	return categoryModulesMap.get(categoryName) ?? [];
}

// Manual overrides for module-replace grouping: each inner array lists the exact module ids that
// can replace each other, taking full precedence over the automatic same-category matching below
// for every id it contains. A module alone in a single-id array (e.g. the Name bar) can't be
// replaced by anything, and nothing can be replaced by it. A module absent from every array here
// falls back to the default "same category" matching. Add more override groups as needed.
const REPLACE_GROUP_OVERRIDES: number[][] = [
	[126], // Name bar — no inputs/outputs, doesn't make sense to swap
	[1, 199], // Keyboard, MonoKey
];

function findOverrideGroup(id: number): number[] | undefined {
	return REPLACE_GROUP_OVERRIDES.find((group) => group.includes(id));
}

// Clavia's real "replace module" group table isn't recoverable (the data-loading routine failed
// to decompile from the original binary), so a group is approximated as "same toolbar category" —
// any two modules sharing a page.name can replace each other, even if that drops some cables or
// params that don't carry over (remapCablesForModule/remapParamValues already drop what doesn't
// match, mirroring the real editor's "cable connections preserved if possible") — unless overridden
// above.
export function areModulesReplaceCompatible(a: ModuleDefinition, b: ModuleDefinition): boolean {
	if (a.id === b.id) return false;
	const overrideGroup = findOverrideGroup(a.id) ?? findOverrideGroup(b.id);
	if (overrideGroup) return overrideGroup.includes(a.id) && overrideGroup.includes(b.id);
	return !!a.page?.name && a.page.name === b.page?.name;
}

export function getReplaceCandidates(moduleTypeId: number, area: 'voice' | 'fx'): ModuleDefinition[] {
	const def = getModule(moduleTypeId);
	if (!def) return [];
	const overrideGroup = findOverrideGroup(def.id);
	if (overrideGroup) {
		return overrideGroup
			.filter((id) => id !== def.id && isValidInArea(id, area))
			.map((id) => getModule(id))
			.filter((m): m is ModuleDefinition => !!m);
	}
	if (!def.page?.name) return [];
	return getModulesByCategory(def.page.name).filter((m) => isValidInArea(m.id, area) && areModulesReplaceCompatible(def, m));
}
